package com.bank.core;

import java.math.BigDecimal;
import java.util.logging.*;

public class PromotionCastingDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // 1) byte + byte promotes to int
        byte a = 10, b = 20;
        int sum = a + b; // result is int, NOT byte
        log.info(() -> "byte 10 + byte 20 = int " + sum + " (promoted to int)");

        // 2) char promotes to int in arithmetic
        char accountType = 'S';
        int next = accountType + 1; // 'S' = 83, +1 = 84
        log.info(() -> "char 'S' + 1 = int " + next + " (char promoted to int)");

        // 3) mixing int and double promotes to double
        int principal = 50000;
        double withInterest = principal * 1.05; // int promoted to double
        log.info(() -> "int 50000 * 1.05 = double " + withInterest + " (promoted to double)");

        // 4) widening is implicit and safe
        int seqInt = 100000;
        long seqLong = seqInt; // int → long, no cast needed
        log.info(() -> "int → long widening (no cast): " + seqLong);

        // 5) narrowing needs explicit cast and can overflow
        int bigValue = 300;
        byte narrowed = (byte) bigValue; // only low 8 bits survive → 44
        log.warning(() -> "int 300 → (byte) = " + narrowed + " (OVERFLOW, only low 8 bits)");

        // 6) long-hand b = b + 1 would NOT compile for a byte; must cast:
        byte counter = 5;
        counter = (byte) (counter + 1); // explicit cast required because (counter + 1) is int
        final byte counterShown = counter;
        log.info(() -> "byte counter = (byte)(counter + 1) = " + counterShown + " (explicit cast)");

        // 7) compound assignment += compiles because it hides a narrowing cast
        byte edge = 127;
        edge += 1; // equivalent to edge = (byte)(edge + 1) → overflow to -128
        final byte edgeShown = edge;
        log.warning(() -> "byte 127 += 1 = " + edgeShown + " (hidden cast → silent overflow)");

        // 8) truncation of a floating cast drops the paise — dangerous for money
        double rupeesWithPaise = 1234.99;
        int truncated = (int) rupeesWithPaise; // truncates toward zero → 1234
        log.warning(() -> "(int) 1234.99 = " + truncated + " (paise dropped — use BigDecimal!)");
        BigDecimal safeMoney = new BigDecimal("1234.99");
        log.info(() -> "BigDecimal keeps exact money = " + safeMoney);
    }
}
